import { readFileSync } from "node:fs";

const all = [0, 1, 2, 3, 4, 5, 6, 7, 8].flatMap((g) => JSON.parse(readFileSync(`g${g}.json`, "utf8")));
const byKey = new Map(all.map((t) => [t.key, t]));

const before = (key, seen = new Set()) => {
  for (const dep of byKey.get(key).deps) {
    if (seen.has(dep)) continue;
    seen.add(dep);
    before(dep, seen);
  }
  return seen;
};

const target = all.find((t) => t.title.includes(process.argv[2])).key;
const chain = [...before(target)].map((k) => byKey.get(k)).sort((a, b) => a.w[0] - b.w[0] || a.key.localeCompare(b.key));
for (const t of chain) console.log(`W${t.w[0]}-W${t.w[1]}  ${t.key}  ${t.title}`);
const goals = new Set([...chain, byKey.get(target)].flatMap((t) => t.needs.match(/\bG\d\b/g) ?? []));
console.log(`\n${target} waits for ${chain.length} tickets in its own goal, and their needs name: ${[...goals].sort().join(" ")}`);
